      \</button\>

      {isLoading && \<p className="loading-status"\>Processing request...\</p\>}

    \</div\>

  );

};

export default CommandPanel;

# 3\. `Loom.tsx` (D3.js Visualization Engine)

This component renders the interactive knowledge graph using D3.js, visualizing nodes and edges.// components/Loom.tsx

import React, { useRef, useEffect } from 'react';

import \* as d3 from 'd3';

import { Node, Edge } from '../types/graph';

import './Loom.css';

interface LoomProps {

  nodes: Node\[\];

  edges: Edge\[\];

  isAnimating: boolean;

}

const Loom: React.FC\<LoomProps\> \= ({ nodes, edges, isAnimating }) \=\> {

  const svgRef \= useRef\<SVGSVGElement | null\>(null);

  useEffect(() \=\> {

    if (\!svgRef.current) return;

    const width \= svgRef.current.clientWidth;

    const height \= svgRef.current.clientHeight;

    const svg \= d3.select(svgRef.current);

    svg.selectAll('\*').remove(); // Clear previous render

    const linkGroup \= svg.append('g').attr('class', 'links');

    const nodeGroup \= svg.append('g').attr('class', 'nodes');

    const simulation \= d3.forceSimulation(nodes)

      .force('link', d3.forceLink\<Node, Edge\>(edges).id(d \=\> d.id).distance(100))

      .force('charge', d3.forceManyBody().strength(-300))

      .force('center', d3.forceCenter(width / 2, height / 2));

    const link \= linkGroup

      .selectAll('line')

      .data(edges)

      .join('line')

      .attr('stroke', '\#999')

      .attr('stroke-opacity', 0.6);

    const node \= nodeGroup

      .selectAll('circle')

      .data(nodes)

      .join('circle')

      .attr('r', 10\)

      .attr('fill', d \=\> {

        switch (d.type) {

          case 'UMB': return '\#4CAF50'; // Green for UMB

          case 'AOP': return '\#2196F3'; // Blue for AOP

          case 'Concept': return '\#FFC107'; // Amber for Concept

          default: return '\#9E9E9E'; // Grey for others

        }

      })

      .attr('stroke', '\#fff')

      .attr('stroke-width', 1.5)

      .call(d3.drag\<SVGCircleElement, Node\>()

        .on('start', dragstarted)

        .on('drag', dragged)

        .on('end', dragended));

    const labels \= nodeGroup

      .selectAll('text')

      .data(nodes)

      .join('text')

      .attr('font-size', '10px')

      .attr('fill', '\#fff')

      .attr('dx', 12\)

      .attr('dy', 4\)

      .text(d \=\> d.name);

    node.append('title').text(d \=\> d.name); // Tooltip for nodes

    simulation.on('tick', () \=\> {

      link

        .attr('x1', d \=\> (d.source as Node).x || 0\)

        .attr('y1', d \=\> (d.source as Node).y || 0\)

        .attr('x2', d \=\> (d.target as Node).x || 0\)

        .attr('y2', d \=\> (d.target as Node).y || 0);

      node

        .attr('cx', d \=\> d.x || 0\)

        .attr('cy', d \=\> d.y || 0);

      labels

        .attr('x', d \=\> d.x || 0\)

        .attr('y', d \=\> d.y || 0);

    });

    if (isAnimating) {

