  public async updateFragment(

    fragmentId: string,

    updates: Partial\<{ content: any; tags: string\[\]; tier: MemoryTier }\>

  ): Promise\<boolean\> {

    const fragment \= this.fragments.get(fragmentId);

    if (\!fragment) {

      console.warn(\`ECM: Fragment with ID ${fragmentId} not found for update.\`);

      return false;

    }

    console.log(\`ECM: Updating fragment ${fragmentId}.\`);

    const updatedFragment \= { ...fragment, version: fragment.version \+ 1 };

    if (updates.content \!== undefined) {

      updatedFragment.content \= updates.content;

      // Recalculate embedding and summary if content changes significantly

      const { embedding, summary } \= await this.geminiService.reprocessMemoryContent(

        updates.content,

        fragment.contentType

      );

      updatedFragment.embedding \= embedding;

      updatedFragment.summary \= summary;

    }

    if (updates.tags \!== undefined) {

      updatedFragment.tags \= \[...new Set(updates.tags)\];

    }

    if (updates.tier \!== undefined) {

      updatedFragment.tier \= updates.tier;

    }

    this.fragments.set(fragmentId, updatedFragment);

    console.log(\`ECM: Fragment ${fragmentId} updated to version ${updatedFragment.version}.\`);

    return true;

  }

  /\*\*

   \* Deletes a memory fragment and all associated links.

   \* @param fragmentId The ID of the fragment to delete.

   \* @returns True if deleted, false if fragment not found.

   \*/

  public deleteFragment(fragmentId: string): boolean {

    if (\!this.fragments.has(fragmentId)) {

      console.warn(\`ECM: Fragment with ID ${fragmentId} not found for deletion.\`);

      return false;

    }

    this.fragments.delete(fragmentId);

    this.links.delete(fragmentId); // Remove links originating from this fragment

    // Remove any links where this fragment is the target

    this.links.forEach((fragmentLinks, sourceFragId) \=\> {

      this.links.set(sourceFragId, fragmentLinks.filter(link \=\> link.targetId \!== fragmentId));

    });

    console.log(\`ECM: Fragment ${fragmentId} and its links deleted.\`);

    return true;

  }

